def simple_math_problem() -> int:
    """There are some kids in camp. Half of the kids are going to soccer camp, and 1/4 of the kids going to soccer camp are going to soccer camp in the morning. 750 kids are going to soccer camp in the afternoon. How many kids there in camp altogether?"""
    total_kids = 750 / (3 / 4) * 2
    return int(total_kids)

def simple_math_problem() -> int:
    """Tom and his friends were filling up water balloons. Tom filled up 3 times as many water balloons as Luke. Luke filled up one fourth as many balloons as Anthony. If Anthony filled up 44 water balloons, how many did Tom fill up?"""
    Anthony_balloons = 44
    Luke_balloons = Anthony_balloons / 4
    Tom_balloons = Luke_balloons * 3
    return int(Tom_balloons)

def simple_math_problem() -> int:
    """Patrick is half the age of his elder brother Robert. If Robert will turn 30 after 2 years, how old is Patrick now?"""
    robert_age_future = 30
    robert_age_now = robert_age_future - 2
    patrick_age_now = robert_age_now / 2
    return int(patrick_age_now)

def simple_math_problem() -> int:
    """Chloe and Max played Mario Kart together. The ratio of Chloe’s wins to Max’s wins is 8:3. Chloe won 24 times. How many times did Max win?"""
    ratio_chloe_to_max = 8 / 3
    chloe_wins = 24
    max_wins = chloe_wins / ratio_chloe_to_max
    return int(max_wins)

def simple_math_problem() -> int:
    """Kirsty collects small models of animals. The last time she bought some, each one cost $0.45. She saves enough to buy 30 models, but when she goes to the shop, she finds out that the price had increased to $0.50. How many models can she buy now?"""
    total_saved = 0.45 * 30
    models_can_buy = total_saved / 0.5
    return int(models_can_buy)

def simple_math_problem() -> int:
    """Tim has 22 cans of soda. Jeff comes by, and takes 6 cans of soda from Tim. Tim then goes and buys another half the amount of soda cans he had left. How many cans of soda does Tim have in the end?"""
    initial_cans = 22
    cans_after_jeff = initial_cans - 6
    final_cans = cans_after_jeff + cans_after_jeff / 2
    return int(final_cans)

def simple_math_problem() -> int:
    """Danny made chocolate cookies for his class and made sure each cookie had exactly 7 chips. He made 4 dozen in total. If the class eats half the cookies, how many chips are left uneaten?"""
    total_cookies = 4 * 12
    uneaten_cookies = total_cookies / 2
    chips_left = uneaten_cookies * 7
    return int(chips_left)
